-- VisualForge AI — Phase 1 schema. All tables carry the VisualForge_ prefix (shared database).
-- NOTE: Postgres folds unquoted identifiers to lowercase, so tables are created as visualforge_*.
-- RLS: clients NEVER read differences of unfinished levels.
create table if not exists VisualForge_images (id uuid primary key default gen_random_uuid(), owner_id uuid, storage_path text not null, width int not null, height int not null, source text not null check (source in ('upload','generated','mock')), expires_at timestamptz default now()+interval '24 hours', created_at timestamptz default now());
create table if not exists VisualForge_generation_jobs (id uuid primary key default gen_random_uuid(), image_id uuid references VisualForge_images(id), mode text not null check (mode in ('game','qc')), status text not null default 'queued', stage text, requested_changes int not null default 7, is_mock boolean not null default false, error text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists VisualForge_levels (id uuid primary key default gen_random_uuid(), job_id uuid references VisualForge_generation_jobs(id), original_image_id uuid references VisualForge_images(id), modified_image_id uuid references VisualForge_images(id), mode text not null, is_mock boolean not null default false, published boolean not null default false, created_at timestamptz default now());
-- differences: NO public select policy until level published AND (game finished by requester) — enforced in API too.
create table if not exists VisualForge_differences (id uuid primary key default gen_random_uuid(), level_id uuid references VisualForge_levels(id) on delete cascade, type text not null, description text not null, bbox jsonb not null, bbox_normalized jsonb not null, mask_url text, severity text default 'medium', verification_status text default 'needs_review', verifier_notes text default '');
create table if not exists VisualForge_game_sessions (id uuid primary key default gen_random_uuid(), level_id uuid references VisualForge_levels(id), player_id uuid, found_ids uuid[] default '{}', mistakes int default 0, hints_used int default 0, score int default 0, finished boolean default false, started_at timestamptz default now(), finished_at timestamptz);
create table if not exists VisualForge_rooms (id uuid primary key default gen_random_uuid(), code text unique not null, host_id uuid, status text default 'lobby', round_number int default 1, expires_at timestamptz default now()+interval '2 hours', created_at timestamptz default now());
create table if not exists VisualForge_room_players (id uuid primary key default gen_random_uuid(), room_id uuid references VisualForge_rooms(id) on delete cascade, player_id uuid, display_name text not null, color text not null, ready boolean default false, score int default 0, unique(room_id, player_id));
create table if not exists VisualForge_rounds (id uuid primary key default gen_random_uuid(), room_id uuid references VisualForge_rooms(id) on delete cascade, level_id uuid references VisualForge_levels(id), round_number int not null, status text default 'pending', starts_at timestamptz, ends_at timestamptz);
-- RACE GUARD: first valid find wins, enforced by the DB itself.
create table if not exists VisualForge_round_finds (id uuid primary key default gen_random_uuid(), round_id uuid references VisualForge_rounds(id) on delete cascade, difference_id uuid references VisualForge_differences(id), player_id uuid not null, found_at timestamptz default now(), unique(round_id, difference_id));
create table if not exists VisualForge_qc_sessions (id uuid primary key default gen_random_uuid(), trainee_id uuid, level_id uuid references VisualForge_levels(id), correct int default 0, missed int default 0, false_positives int default 0, accuracy numeric, duration_sec int, created_at timestamptz default now());
create table if not exists VisualForge_qc_responses (id uuid primary key default gen_random_uuid(), session_id uuid references VisualForge_qc_sessions(id) on delete cascade, click jsonb not null, was_correct boolean not null, difference_id uuid);
create table if not exists VisualForge_datasets (id uuid primary key default gen_random_uuid(), name text not null, note text default 'synthetic — validate before industrial use', created_at timestamptz default now());
create table if not exists VisualForge_dataset_samples (id uuid primary key default gen_random_uuid(), dataset_id uuid references VisualForge_datasets(id) on delete cascade, level_id uuid references VisualForge_levels(id), approved boolean, verified boolean not null default false);
create table if not exists VisualForge_ai_calls (id uuid primary key default gen_random_uuid(), job_id uuid, model text not null, operation text not null, latency_ms int, estimated_cost_usd numeric, is_mock boolean not null default false, created_at timestamptz default now());
alter table VisualForge_images enable row level security;
alter table VisualForge_differences enable row level security;
alter table VisualForge_levels enable row level security;
-- Deliberately restrictive default: no anon select on differences (server role only, validated click API).
create policy "levels public read if published" on VisualForge_levels for select using (published = true);
create policy "images public read" on VisualForge_images for select using (true);
insert into storage.buckets (id, name, public) values ('visualforge-originals','visualforge-originals',true),('visualforge-generated','visualforge-generated',true),('visualforge-masks','visualforge-masks',true) on conflict (id) do nothing;
